            f.settled();TaskStoreTeamWriteHost.DraftScopePage page=f.host.newDraftScopePage(f.coordinator,f.run);page.setForeground(true);TaskStore.TeamDraftReview review=page.review();JSONObject shown=review.view();assertEquals(5,shown.getInt("parentRemainingOperations"));assertFalse(shown.getBoolean("canCompleteMinimumPlan"));JSONObject before=f.tasks.teamBudgetSnapshot(f.run);assertThrows(SecurityException.class,()->page.approve(review,shown.getString("digest")));assertEquals(before.toString(),f.tasks.teamBudgetSnapshot(f.run).toString());assertEquals("not_authorized",page.snapshot().getString("state"));
            page.close();assertThrows(SecurityException.class,()->page.approve(review,shown.getString("digest")));assertEquals("原文件\n",f.files.files.read(f.files.project,"src/a.txt",0).getString("content"));
